{
  "title": "k-平移距离的定义可视化",
  "preferred_geogebra_app": "geometry",
  "execution_mode": "command_only",
  "math_meaning_summary": "该可视化逐步构建了'k-平移距离'的几何定义。它展示了对于给定的点A, B和一个圆，如何找到两条与线段AB平行且等长的弦，并由此确定两个可能的平移向量。'k'值最终被确定为这两个平移距离中较大的一个。",
  "object_naming_convention": "遵循数学惯例，初始点为A和B，圆心为O，平移后的点为A'_1, A'_2。",
  "commands": [
    {
      "step": 1,
      "purpose": "创建交互式步骤控制器。",
      "command": "step = Slider(0, 4, 1)"
    },
    {
      "step": 2,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "O = (0,0)"
    },
    {
      "step": 3,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "c = Circle(O, 1)"
    },
    {
      "step": 4,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "A = (-1, sqrt(3))"
    },
    {
      "step": 5,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "B = (-1/2, sqrt(3)/2)"
    },
    {
      "step": 6,
      "purpose": "创建初始线段。",
      "command": "s_AB = Segment(A, B)"
    },
    {
      "step": 7,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "M_AB = Midpoint(A, B)"
    },
    {
      "step": 8,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "dist_OM = sqrt(1 - Distance(A, M_AB)^2)"
    },
    {
      "step": 9,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "dir_perp = PerpendicularVector(Vector(B - A))"
    },
    {
      "step": 10,
      "purpose": "计算两个可能的弦的中点。",
      "command": "M1 = O + dist_OM * UnitVector(dir_perp)"
    },
    {
      "step": 11,
